# Check if matching rows are permutations of each other
import numpy as np

def is_permutation(row1, row2):
    return sorted(row1) == sorted(row2)

matching_rows = []
for i in range(len(grid)):
    for j in range(i+1, len(grid)):
        if is_permutation(grid[i], grid[j]):
            matching_rows.append((i, j))

print("Matching row pairs (same colors):")
for i, j in matching_rows:
    print(f"  Row {i} ↔ Row {j}")
    print(f"    Row {i}: {grid[i]}")
    print(f"    Row {j}: {grid[j]}")

# Let's check if they might be shifted
def is_shift(row1, row2):
    n = len(row1)
    for shift in range(n):
        if all(row1[k] == row2[(k + shift) % n] for k in range(n)):
            return f"shift={shift}"
    return None

print("\nChecking if matching rows are shifts of each other:")
for i, j in matching_rows:
    shift_info = is_shift(grid[i], grid[j])
    print(f"  Row {i} → Row {j}: {shift_info}")

